-- =============================================================================
-- Datos de ejemplo para analisis - generado por generate_seed.py (no editar a mano)
-- Empresa ficticia de software e implementacion de ERP; 12 quincenas de 2026.
-- INSS e IR son APROXIMADOS: sirven para practicar analisis, no para planilla legal.
--
-- REEMPLAZA los datos de ejemplo del esquema. Requiere schema_planilla_pymes_postgres.sql.
-- Uso: psql -d planilla_pymes -f seed_planilla_postgres.sql
-- =============================================================================
SET search_path TO planilla;
BEGIN;
TRUNCATE planilla_movimientos, planilla_detalle, planillas, asistencia_resumen, salary_advances,
         prestamos_empleado, periodos_pago, conceptos_nomina, empleados, departamentos, usuarios, empresas
         RESTART IDENTITY CASCADE;

