) AS v (numero, codigo, concepto, descripcion, cantidad, monto)
JOIN planillas pl ON pl.numero = v.numero
JOIN empleados e ON e.codigo_empleado = v.codigo
JOIN planilla_detalle d ON d.planilla_id = pl.id AND d.empleado_id = e.id
JOIN conceptos_nomina c ON c.codigo = v.concepto;

