INSERT INTO salary_advances (empresa_id, empleado_id, referencia, fecha_solicitud, fecha_aprobacion, fecha_entrega,
                             monto_aprobado, saldo_pendiente, cuotas_pactadas, cuotas_pagadas, estado)
SELECT 1, e.id, v.ref, v.solicitud::date, v.aprobacion::date, v.entrega::date, v.monto, v.saldo, v.cuotas, v.pagadas,
       v.estado::estado_salary_advance
FROM (VALUES
    ('SA-2026-001', 'EMP-004', '2026-01-12', '2026-01-13', '2026-01-13', 3000.00, 0.00, 2, 2, 'descontado'),
    ('SA-2026-002', 'EMP-007', '2026-01-28', '2026-01-28', '2026-01-28', 2500.00, 0.00, 1, 1, 'descontado'),
    ('SA-2026-003', 'EMP-013', '2026-02-09', '2026-02-10', '2026-02-10', 4000.00, 0.00, 2, 2, 'descontado'),
    ('SA-2026-004', 'EMP-016', '2026-02-25', '2026-02-26', '2026-02-26', 3500.00, 0.00, 2, 2, 'descontado'),
    ('SA-2026-005', 'EMP-024', '2026-03-27', '2026-03-28', '2026-03-28', 5000.00, 0.00, 2, 2, 'descontado'),
    ('SA-2026-006', 'EMP-003', '2026-04-08', '2026-04-09', '2026-04-09', 2000.00, 0.00, 1, 1, 'descontado'),
    ('SA-2026-007', 'EMP-012', '2026-05-11', '2026-05-12', '2026-05-12', 6000.00, 0.00, 3, 3, 'descontado'),
    ('SA-2026-008', 'EMP-015', '2026-06-19', '2026-06-20', '2026-06-20', 3000.00, 1500.00, 2, 1, 'entregado'),
    ('SA-2026-009', 'EMP-018', '2026-06-26', NULL, NULL, 4500.00, 4500.00, 2, 0, 'solicitado'),
