INSERT INTO prestamos_empleado (empresa_id, empleado_id, referencia, monto_total, saldo_actual, cuota_periodica, fecha_inicio, estado)
SELECT 1, e.id, v.ref, v.monto, v.saldo, v.cuota, v.inicio::date, v.estado::estado_prestamo
FROM (VALUES
    ('PREST-001', 'EMP-002', 30000.00, 3750.00, 1250.00, '2025-07-01', 'activo'),
    ('PREST-002', 'EMP-009', 12000.00, 0.00, 1000.00, '2025-11-01', 'cancelado'),
    ('PREST-003', 'EMP-021', 20000.00, 10000.00, 1000.00, '2026-02-01', 'activo')
) AS v (ref, codigo, monto, saldo, cuota, inicio, estado)
JOIN empleados e ON e.codigo_empleado = v.codigo;

-- Totales del encabezado calculados desde el detalle
UPDATE planillas p
SET total_ingresos = d.ingresos, total_deducciones = d.deducciones, total_neto = d.neto
FROM (SELECT planilla_id, SUM(ingresos) AS ingresos, SUM(deducciones) AS deducciones, SUM(salario_neto) AS neto
      FROM planilla_detalle GROUP BY planilla_id) d
WHERE d.planilla_id = p.id;

COMMIT;
